// Assets da carta, embutidos como data URI: `html-to-image` serializa o nó em
// um SVG isolado, e recurso por URL externa sai em branco no arquivo exportado.
// Gerados de `public/images/` com ImageMagick; regerar quando a marca mudar.

/** Mascote recortado, padrão quando a pessoa não envia foto. */
export const MASCOTE_DATA_URI =
  "data:image/webp;base64,";

/** Faixa de grafismo marajoara, verde. */
export const GRAFISMO_VERDE_DATA_URI =
  "data:image/webp;base64,";

/** Lockup da marca. */
export const LOGO_DATA_URI =
  "data:image/webp;base64,";
